// Keep the original photographic puppet; constrain its lowest modeled sole to a ground line.
import {paintCutoutWalk,cutoutWalkPose,cutoutWalkDefaults} from './cutout-walk.js?v=motion-v70';
export const groundedWalkDefaults={groundedWalkEnabled:true,groundedWalkStrength:1,groundedWalkGround:530};
export function groundedWalkState(time,input={}){const f={...cutoutWalkDefaults,...groundedWalkDefaults,...input},pose=cutoutWalkPose(time,f),rig=f.walkRig,rotate=(p,o,d)=>{const a=d*Math.PI/180,x=p[0]-o[0],y=p[1]-o[1];return [o[0]+x*Math.cos(a)-y*Math.sin(a),o[1]+x*Math.sin(a)+y*Math.cos(a)]},points=[];for(const side of ['back','front'])for(const p of (input.groundedWalkHulls?.[side]||rig.parts[side+'Shin'])){const knee=rig[side+'Knee'],q=rotate(rotate(p,knee,pose[side+'Knee']),rig.hip,pose[side]);points.push(q);}return {pose,soleY:Math.max(...points.map(p=>p[1]))+pose.bob,ground:f.groundedWalkGround};}
const hullCache=new WeakMap();function sourceFootHulls(image,rig){const key=JSON.stringify([rig,image.src,image._assetRevision]),old=hullCache.get(image);if(old?.key===key)return old.hulls;const cv=Object.assign(document.createElement('canvas'),{width:rig.width,height:rig.height}),c=cv.getContext('2d');c.drawImage(image,0,0,rig.width,rig.height);const data=c.getImageData(0,0,rig.width,rig.height).data,inside=(x,y,poly)=>{let yes=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const [a,b]=poly[i],[u,v]=poly[j];if((b>y)!==(v>y)&&x<(u-a)*(y-b)/(v-b)+a)yes=!yes;}return yes},hulls={};for(const side of ['back','front']){const poly=rig.parts[side+'Shin'],points=[];for(let y=Math.max(0,Math.floor(Math.min(...poly.map(p=>p[1]))));y<rig.height;y+=3)for(let x=0;x<rig.width;x+=3)if(data[(y*rig.width+x)*4+3]>160&&inside(x,y,poly))points.push([x,y]);points.sort((a,b)=>a[0]-b[0]||a[1]-b[1]);const cross=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]),half=ps=>{const h=[];for(const p of ps){while(h.length>1&&cross(h.at(-2),h.at(-1),p)<=0)h.pop();h.push(p)}return h};hulls[side]=points.length?half(points).slice(0,-1).concat(half([...points].reverse()).slice(0,-1)):poly;}hullCache.set(image,{key,hulls});return hulls;}
export function paintGroundedWalk(c,image,time,rect,input={}){if(!(image?.naturalWidth||image?.width))return false;const f={...groundedWalkDefaults,...input},s=groundedWalkState(time,{...input,groundedWalkHulls:sourceFootHulls(image,input.walkRig||cutoutWalkDefaults.walkRig)}),[x,y,w,h]=rect,height=input.walkRig?.height||cutoutWalkDefaults.walkRig.height,correction=(s.ground-y-s.soleY*h/height)*f.groundedWalkStrength;return paintCutoutWalk(c,image,time,[x,y+correction,w,h],input);}
